[
  {
    "alert_id": "ALERT_001",
    "title": "Rising creatinine and declining eGFR on TDF",
    "message": "Guidelines state that in patients on TDF, it is important to check creatinine (eGFR), as intercurrent illnesses with dehydration or sepsis may cause renal deterioration. This patient's creatinine has steadily risen from 0.9 mg/dL (2020) to 1.4 mg/dL (2026), with eGFR now 52 mL/min/1.73m². TDF is a known cause of proximal tubular toxicity and progressive renal impairment. Evidence for drug attribution: the gradual decline aligns with chronic TDF nephrotoxicity, and urinalysis shows proteinuria (1+), consistent with tubular damage. Evidence against: the patient has no oedema or hypertension, and occasional ibuprofen use (2–3×/week for 6 months) may also contribute to renal decline. The progressive trend over 6 years is concerning even though no single value was flagged.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Evaluate TDF-related nephrotoxicity. Consider switching TDF to TAF or ABC. Discontinue or minimise ibuprofen use. Refer for nephrology evaluation if eGFR continues to decline.",
    "citations": [
      {"page_number": 40, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p40_c2"}
    ]
  },
  {
    "alert_id": "ALERT_002",
    "title": "Ibuprofen plus TDF compounding renal risk",
    "message": "Guidelines highlight the importance of monitoring renal function in patients on TDF, noting that intercurrent conditions can worsen renal function. This patient has declining eGFR (52 mL/min/1.73m²) with rising creatinine and is taking ibuprofen 400 mg 2–3 times weekly for 6 months. NSAIDs reduce prostaglandin-mediated renal perfusion and can accelerate kidney injury, especially combined with TDF nephrotoxicity and existing renal impairment. The concurrent use of TDF and chronic NSAID exposure represents a compounding risk for further renal decline. No alternative explanation for the proteinuria has been investigated.",
    "issue_type": "drug_interaction",
    "severity": "high",
    "recommended_action": "Counsel patient to discontinue ibuprofen or switch to paracetamol for headache relief. Monitor renal function closely. Assess whether TDF should be replaced with a less nephrotoxic agent.",
    "citations": [
      {"page_number": 40, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p40_c2"}
    ]
  },
  {
    "alert_id": "ALERT_003",
    "title": "No clinician assessment or plan documented",
    "message": "Guidelines recommend regular virological monitoring and clinical review for patients on DTG-based ART. This patient has a rising creatinine trend, proteinuria, declining eGFR, and concurrent ibuprofen use, yet no assessment or plan was documented at today's visit. The clinician did not address the renal abnormalities, evaluate the fatigue complaint, or outline monitoring or management steps. This represents a significant gap in care for a patient with evidence of progressive renal impairment on a nephrotoxic regimen.",
    "issue_type": "plan_review",
    "severity": "high",
    "recommended_action": "Document a clinical assessment addressing the creatinine trend, proteinuria, and ibuprofen use. Formulate a management plan including renal monitoring, medication review, and possible TDF substitution.",
    "citations": [
      {"page_number": 32, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p32_c1"}
    ]
  },
  {
    "alert_id": "ALERT_004",
    "title": "Proteinuria on urinalysis warrants investigation",
    "message": "Guidelines emphasise renal monitoring in patients on TDF. This patient's urinalysis shows protein 1+ and glucose trace, alongside eGFR of 52 mL/min/1.73m² and a 6-year creatinine rise from 0.9 to 1.4 mg/dL. Proteinuria may reflect TDF-induced proximal tubular dysfunction, but diabetes mellitus (suggested by glycosuria with normal Hb) and other glomerular causes should be excluded. No further renal workup or referral was documented. The combination of proteinuria, glycosuria, and declining eGFR requires structured evaluation beyond routine monitoring.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Perform fasting blood glucose, urine ACR, and renal ultrasound. Refer to nephrology if proteinuria persists. Evaluate for TDF-induced Fanconi syndrome versus other renal pathology.",
    "citations": [
      {"page_number": 40, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p40_c2"}
    ]
  }
]
